import{_ as t,o as a,c as o,a2 as d}from"./chunks/framework.CNDaxUod.js";const u=JSON.parse('{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"guide/configuration.md","filePath":"guide/configuration.md"}'),s={name:"guide/configuration.md"};function i(r,e,n,h,l,c){return a(),o("div",null,[...e[0]||(e[0]=[d(`<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p>AsyncUp is configured in two layers:</p><ol><li><strong>Bootstrap</strong> — a handful of environment variables (where&#39;s the database, what port, the dashboard token). Set once, rarely touched.</li><li><strong>Everything else</strong> — managed in the <strong><a href="./dashboard.html">web app</a> Settings page</strong> and stored in your database, with secrets encrypted (AES-256-GCM via <code>SECRET_KEY</code>). Changes apply immediately, no restart.</li></ol><h2 id="bootstrap-environment-variables" tabindex="-1">Bootstrap environment variables <a class="header-anchor" href="#bootstrap-environment-variables" aria-label="Permalink to &quot;Bootstrap environment variables&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Purpose</th></tr></thead><tbody><tr><td><code>PORT</code></td><td><code>8080</code></td><td>Webhook + dashboard port</td></tr><tr><td><code>DB_PATH</code></td><td><code>./data/standup.db</code></td><td>SQLite database file (default storage)</td></tr><tr><td><code>DATABASE_URL</code></td><td><em>(empty)</em></td><td>Bring-your-own PostgreSQL — when set, SQLite is skipped (see <a href="./deployment.html#database-embedded-or-bring-your-own">Deployment</a>)</td></tr><tr><td><code>DB_SSL</code></td><td>from URL <code>sslmode</code></td><td>Postgres TLS: <code>require</code> (encrypt, no verify — default for managed DBs), <code>verify-full</code>, or <code>disable</code></td></tr><tr><td><code>DB_SSL_CA</code></td><td><em>(empty)</em></td><td>CA bundle path for <code>DB_SSL=verify-full</code></td></tr><tr><td><code>DASHBOARD_TOKEN</code></td><td><em>(empty)</em></td><td>Operator token for the web app and the JSON API — the way in before Google or SAML sign-in is configured. Disabled while empty</td></tr><tr><td><code>SECRET_KEY</code></td><td>—</td><td>Encrypts stored secrets. Generate with <code>openssl rand -hex 32</code>. Required (except <code>ADAPTER=fake</code>)</td></tr><tr><td><code>ADAPTER</code></td><td><code>google</code></td><td><code>google</code> for production, <code>fake</code> for a console demo</td></tr><tr><td><code>TENANT_ID</code></td><td><code>default</code></td><td>Tenant identifier — leave as is for self-hosted installs</td></tr></tbody></table><h2 id="dashboard-settings-stored-in-the-database" tabindex="-1">Dashboard settings (stored in the database) <a class="header-anchor" href="#dashboard-settings-stored-in-the-database" aria-label="Permalink to &quot;Dashboard settings (stored in the database)&quot;">​</a></h2><p>Open <code>https://&lt;your-host&gt;/app</code>, sign in with the operator token → <strong>Settings</strong>:</p><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td>Audience (GCP project number and/or app URL)</td><td>Verifies incoming webhooks are signed by Google Chat — space/comma separated when both</td></tr><tr><td>Service-account key (JSON)</td><td>Paste the downloaded key file — used for Chat API calls and Calendar OOO. Empty = <a href="https://cloud.google.com/docs/authentication/application-default-credentials" target="_blank" rel="noreferrer">Application Default Credentials</a> (e.g. Cloud Run service identity)</td></tr><tr><td>Default timezone</td><td>Assigned to newly created standups</td></tr><tr><td>Calendar OOO sync</td><td>Auto-mark people away on out-of-office days</td></tr><tr><td>Workspace admin email</td><td>Enables Directory API lookups (email + admin status by Chat user id). With it, Calendar OOO covers people who never interacted with the bot</td></tr><tr><td>OAuth client ID / secret</td><td>Enables <a href="./dashboard.html#signing-in">Sign in with Google</a>: Workspace admins get the admin console, everyone else the <code>/me</code> user console</td></tr><tr><td>SAML IdP entity / SSO URL / cert</td><td>Enables <a href="./enterprise-sso.html">SAML sign-in</a> with any IdP; admin via IdP group and/or Google Directory</td></tr><tr><td>SCIM provisioning token</td><td>Enables the <a href="./enterprise-sso.html#scim-provisioning">SCIM 2.0 endpoint</a> at <code>/scim/v2</code> for Okta/Entra/OneLogin</td></tr><tr><td>Scheduler tick token</td><td>Authorizes <code>POST /tick</code> for external cron</td></tr><tr><td>CSV export token</td><td>Enables <code>GET /export</code> (off until generated)</td></tr></tbody></table><p>Secrets are write-only: the UI shows <em>that</em> they&#39;re configured (and e.g. the service account&#39;s email), never the material itself.</p><h2 id="endpoints" tabindex="-1">Endpoints <a class="header-anchor" href="#endpoints" aria-label="Permalink to &quot;Endpoints&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Purpose</th></tr></thead><tbody><tr><td><code>POST /chat/events</code></td><td>Google Chat webhook — point the Chat app here</td></tr><tr><td><code>POST /tick</code></td><td>Manually advance the scheduler (for external cron). Requires <code>Authorization: Bearer &lt;tick token&gt;</code> when one is set</td></tr><tr><td><code>GET /export?standupId=N&amp;days=30</code></td><td>CSV download (long format). Requires the export token; disabled until one is generated</td></tr><tr><td><code>GET /app</code></td><td><a href="./dashboard.html">Web app</a> — setup, console, settings</td></tr><tr><td><code>GET /app/me</code></td><td><a href="./dashboard.html">Personal page</a> — own standups + self-service</td></tr><tr><td><code>/auth/*</code></td><td>Google and <a href="./enterprise-sso.html">SAML</a> sign-in</td></tr><tr><td><code>/scim/v2/*</code></td><td><a href="./enterprise-sso.html#scim-provisioning">SCIM 2.0 provisioning</a></td></tr><tr><td><code>GET /healthz</code></td><td>Liveness check (pings the database)</td></tr></tbody></table><p>Every credential-checking surface sits behind a shared rate limiter (60 requests/min/IP). The full per-route table with auth requirements is in the <a href="./handbook.html#42-http-endpoints">Handbook reference</a>.</p><h2 id="outbound-webhooks" tabindex="-1">Outbound webhooks <a class="header-anchor" href="#outbound-webhooks" aria-label="Permalink to &quot;Outbound webhooks&quot;">​</a></h2><p>Give a standup a <strong>Webhook URL</strong> (dashboard → standup page) and AsyncUp POSTs JSON to it as things happen — the cheap path into Sheets (Apps Script), Zapier/n8n, or your own service:</p><ul><li><code>{&quot;event&quot;: &quot;submission&quot;, &quot;standup&quot;: {…}, &quot;date&quot;, &quot;user&quot;, &quot;answers&quot;, &quot;mood&quot;, &quot;late&quot;, &quot;edited&quot;}</code> — on every submission and edit.</li><li><code>{&quot;event&quot;: &quot;wrap_up&quot;, &quot;standup&quot;: {…}, &quot;date&quot;, &quot;summary&quot;: {…}}</code> — when the run closes (same numbers as the posted wrap-up).</li></ul><p>Deliveries time out after 5 s and failures are only logged — a dead webhook never breaks the standup.</p><p>Every delivery is signed: the <code>X-AsyncUp-Signature</code> header carries <code>sha256=&lt;hex&gt;</code>, the HMAC-SHA256 of the raw request body with the standup&#39;s signing secret. The secret is shown on the standup&#39;s dashboard page (derived from <code>SECRET_KEY</code>, so rotating <code>SECRET_KEY</code> rotates it). Verify it in your receiver and reject anything that doesn&#39;t match:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> expected</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;sha256=&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> crypto.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">createHmac</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;sha256&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">SECRET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">).</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">update</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(rawBody).</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">digest</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;hex&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">crypto.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">timingSafeEqual</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(Buffer.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(header), Buffer.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(expected));</span></span></code></pre></div><h2 id="data" tabindex="-1">Data <a class="header-anchor" href="#data" aria-label="Permalink to &quot;Data&quot;">​</a></h2><p>All state — standups, participants, admins, runs, submissions, blockers, app settings — lives either in a single SQLite file (<code>DB_PATH</code>, the default) or in your own PostgreSQL (<code>DATABASE_URL</code>).</p><blockquote><p><strong>Managed Postgres TLS:</strong> RDS / Cloud SQL / Neon / Supabase present a certificate signed by their own CA. AsyncUp treats <code>sslmode=require</code> as &quot;encrypt but don&#39;t verify the cert&quot; (the libpq default every other client uses), so <code>DATABASE_URL=…?sslmode=require</code> connects out of the box. For strict verification set <code>DB_SSL=verify-full</code> and point <code>DB_SSL_CA</code> at the provider&#39;s CA bundle. (Earlier builds inherited node-pg&#39;s stricter default and crash-looped with <code>SELF_SIGNED_CERT_IN_CHAIN</code> — that&#39;s fixed.)</p></blockquote><p>Back up the file or use your database&#39;s backup story; stored secrets are encrypted, so backups are safe to ship off-box as long as <code>SECRET_KEY</code> stays out of them. Schema migrations run automatically on startup in both modes, so upgrading AsyncUp is just deploying the new image. Graceful shutdown on SIGTERM included.</p>`,22)])])}const g=t(s,[["render",i]]);export{u as __pageData,g as default};
